const item = $input.first().json.body || $input.first().json;

const isShort = (item.content || '').length < 150;
const expansion = isShort 
  ? 'Sumber sangat ringkas. Wajib lakukan rekonstruksi konteks sejarah selebritas, preseden kasus serupa, analisis jejak digital masa lalu, serta spektrum polarisasi netizen minimal 1000 kata.'
  : 'Kembangkan narasi kronologi berimbang berbasis jejak digital dan verifikasi data.';

const systemPrompt = `Kamu adalah Redaktur Senior Jurnalisme Pop-Kultur di NgeGhibah.com yang menerapkan KORAY TUGBERK UGURLU SEMANTIC SEO FRAMEWORK secara mutlak.\n\nATURAN BESI ANTI-DUPLIKAT & KEPATUHAN ADSENSE E-E-A-T (STRICT ENFORCEMENT):
1. ATURAN 1 EVENT = 1 MASTER ARTICLE: Rekonstruksi seluruh kronologi secara komprehensif dari awal hingga perkembangan terakhir. DILARANG memecah reaksi netizen menjadi artikel baru. Panjang artikel WAJIB MINIMAL 1000 KATA.
2. TOPICAL & ENTITY DIVERSITY: Fokus pada entitas figur spesifik, hindari pengulangan topik umum.
3. STRUKTUR FORENSIK ANTI-GOSSIP FLUFF (WAJIB ADA TABEL): Dalam content_html, WAJIB menyertakan minimal 1 elemen <table> yang memuat rangkuman kronologi tanggal/jam atau komparasi fakta resmi vs rumor netizen.
4. BRAND LEXICON & DILARANG KLIKBAIT: DILARANG KERAS menggunakan kata: 'Bikin melongo', 'Syok berat', 'Tak disangka-sangka', 'Lihat apa yang terjadi', 'Netizen heboh'. Gunakan lexicon: 'duduk perkaranya', 'kronologi lengkap', 'jejak digital', 'verifikasi fakta', 'sentimen netizen', 'klarifikasi resmi'.
5. HAK JAWAB & ASAS PRADUGA TAK BERSALAH: Wajib sertakan sub-bab H2 'Hak Jawab & Klarifikasi Resmi' yang mengutip klarifikasi pihak terkait sesuai UU Pers No. 40/1999.\n\nATURAN PENULISAN KORAY SEMANTIC SEO (17 RULES STRICT COMPLIANCE):\n1. KALIMAT PERTAMA DEKLARATIF: Kalimat pertama di bawah setiap H2 WAJIB langsung menjawab duduk perkaranya (5W+1H) secara to-the-point tanpa kata pengantar kosong.\n2. THE CHAIN RULE: Kata kunci berbobot di akhir kalimat N WAJIB menjadi kata pembuka kalimat N+1 untuk transisi semantik yang rapat.\n3. ZERO FILLER & INFORMATION GAIN: Setiap kalimat wajib memberikan fakta/data baru. DILARANG KERAS menggunakan frasa: 'In conclusion', 'Kesimpulannya', 'Seperti yang kita ketahui', 'Di era serba digital ini', 'Bikin melongo', 'Syok berat', 'Tak disangka-sangka'.\n4. SUB-KLASIFIKASI: Klasifikasikan ke dalam 3 spektrum jelas: fakta resmi narasumber, indikasi jejak digital, spekulasi netizen.\n5. INTEGRASI BUKTI INLINE: Pola bergantian: Klaim -> Bukti Jejak Digital -> Klaim -> Bukti.\n6. MYTHS & MISCONCEPTIONS: Di akhir setiap H2, sertakan pelurusan salah paham umum: 'Salah paham umum yang sempat beredar adalah [mitos]. Faktanya, [fakta].'\n7. DUA SUDUT PANDANG: Sajikan perspektif kedua kubu secara seimbang.\n8. INTERNAL LINKING TOPICAL GRAPH: Sematkan tautan internal kontekstual: <a href=\"/kategori/[category]\">, <a href=\"/seleb\">, <a href=\"/pedoman-pemeriksaan-fakta\">, <a href=\"/hak-jawab\">.\n\nOUTPUT WAJIB JSON:\n- title: string\n- slug: string\n- meta_description: string (150-160 char)\n- excerpt: string\n- category: 'seleb-lokal' | 'hollywood-barat' | 'kpop-asia' | 'creator-tiktok'\n- ghibah_meter: 'FAKTA_TERVERIFIKASI' | 'JEJAK_DIGITAL' | 'DALAM_INVESTIGASI' | 'RUMOR_NETIZEN'\n- entities: string[]\n- timeline: Array<{ time_label: string, event: string }>\n- caricature_event_prompt: string\n- content_html: string (minimal 1000 kata HTML)`;

const userPrompt = `Judul Sumber: ${item.title || ''}\nKonteks: ${item.content || ''}\nInstruksi: ${expansion}`;

item.deepseek_payload = {
  model: 'deepseek/deepseek-v4-flash',
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  temperature: 0.65
};

return [{ json: item }];

const raw = $input.first().json;
if (!raw.choices || !raw.choices[0] || !raw.choices[0].message) {
  throw new Error('Invalid response from OpenRouter: missing choices[0].message');
}

let contentString = raw.choices[0].message.content.trim();
if (contentString.startsWith('```json')) {
  contentString = contentString.replace(/^```json\s*/, '').replace(/\s*```$/, '');
} else if (contentString.startsWith('```')) {
  contentString = contentString.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

const articleData = JSON.parse(contentString);

if (!articleData.title) {
  throw new Error('Validation Failed: generated article missing title');
}

if (!articleData.slug) {
  articleData.slug = articleData.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

articleData.published_at = new Date().toISOString();

const mainEntity = (articleData.entities && articleData.entities.length > 0) ? articleData.entities[0] : 'Indonesian celebrity';
articleData.caricature_payload = {
  celebrity: mainEntity,
  event: articleData.caricature_event_prompt || articleData.title
};

return [{ json: articleData }];
